actions.script:
const vault = (name, parameters) => {
    const out = ec.service.sync().name('org.moqui.security.VaultServices.' + name).requireNewTransaction(true).parameters(parameters || {}).call()
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    return out
}
// SRI of a webroot file: sha256 of its bytes as base64
const base64 = (hex) => {
    const table = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    const bytes = []
    for (let i = 0; i + 1 < hex.length; i += 2) bytes.push(parseInt(hex.slice(i, i + 2), 16))
    let text = ''
    for (let i = 0; i < bytes.length; i += 3) {
        const n = (bytes[i] << 16) | ((bytes[i + 1] || 0) << 8) | (bytes[i + 2] || 0)
        text += table[(n >> 18) & 63] + table[(n >> 12) & 63] + (i + 1 < bytes.length ? table[(n >> 6) & 63] : '=') + (i + 2 < bytes.length ? table[n & 63] : '=')
    }
    return text
}
const sri = (file) => 'sha256-' + base64(ec.resource.digest('component://webroot/screen/webroot/js/vault/' + file, 'sha256'))
try {
    const module = ec.resource.getLocationReference('component://webroot/screen/webroot/js/vault/moqui_vault.wasm')
    if (!module || !module.getExists()) throw new Error('The vault module is not built: ./moq build or scripts/vault-wasm.sh')
    const got = vault('get#Vault', {vaultId})
    const deposited = Array.from(vault('list#VaultItems', {vaultId}).itemList || [])
        .filter(item => item.itemKeyWrapEnumId === 'VwDeposit')
        .map(item => ({vaultItemId: item.vaultItemId, revision: item.revision, keyVersion: item.keyVersion,
            wrappedItemKey: item.wrappedItemKey, vaultItemTypeId: item.vaultItemTypeId, bindingKey: item.bindingKey,
            itemName: item.itemName}))
    ec.web.sendJsonResponse({vaultName: got.vault.vaultName, keyVersion: got.vault.keyVersion, roleEnumId: got.vault.roleEnumId,
        entries: got.entries, wraps: got.wraps, depositWrappedPrivate: got.depositWrappedPrivate || null, deposited,
        keyChecks: vault('list#KeyChecks').keyCheckList, personal: vault('get#PersonalKey'),
        integrity: {client: sri('VaultClient.js'), worker: sri('VaultWorker.js'), wasm: sri('moqui_vault.wasm')}})
} catch (err) {
    ec.message.clearErrors()
    ec.web.sendJsonResponse({errors: String(err.message || err)})
}

const out = ec.service.sync().name('org.moqui.security.VaultServices.get#WrappedPersonalKey').requireNewTransaction(true).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({personalKeyId: out.personalKeyId, userId: out.userId, public: out.public, passphraseWrap: out.passphraseWrap})

const out = ec.service.sync().name('org.moqui.security.VaultServices.take#VaultDeposit').requireNewTransaction(true)
    .parameters({vaultItemId, expectedRevision, keyVersion, wrappedItemKey}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({revision: out.revision})
